// DecodeError identifies and decodes a declared custom error.
func (c *DiesisSettlementRouterBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("BalanceDeltaMismatch(uint256,uint256)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeBalanceDeltaMismatchError(raw)
	}
	if definition, err := c.customError("OwnableInvalidOwner(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOwnableInvalidOwnerError(raw)
	}
	if definition, err := c.customError("OwnableUnauthorizedAccount(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeOwnableUnauthorizedAccountError(raw)
	}
	if definition, err := c.customError("ReentrancyGuardReentrantCall()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeReentrancyGuardReentrantCallError(raw)
	}
	if definition, err := c.customError("SafeERC20FailedOperation(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeSafeERC20FailedOperationError(raw)
	}
	if definition, err := c.customError("TokenNotAllowed(address)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeTokenNotAllowedError(raw)
	}
	if definition, err := c.customError("ZeroAddress()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroAddressError(raw)
	}
	if definition, err := c.customError("ZeroAmount()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroAmountError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
